((SELECT id FROM subprocesos WHERE codigo='SP010101'),'A010101003','Realizar Direccionamiento, Implantación y Seguimiento de la Estrategia','INICIA: Prospectiva y análisis del entorno. INCLUYE: Mapa estratégico, CMI corporativo, planes de negocio articulados, proyecciones 5 años. TERMINA: PEC aprobado y comunicado.','% Objetivos estratégicos con meta cumplida\nCumplimiento PEC semestral','Jefe Unidad Prospectiva Estratégica','Plan Estratégico Corporativo (PEC) vigente\nMapa estratégico y CMI\nProyecciones financieras 5 años','Orienta el banco de proyectos de GUENAA (expansión A&A), GUENE (Plan SDL, EBIE) y GUENTIC (expansión red TIC).',FALSE,NULL,1),

((SELECT id FROM subprocesos WHERE codigo='SP010101'),'A010101347','Planear y Evaluar la Gestión del Portafolio Corporativo','INICIA: Priorización estratégica del portafolio. INCLUYE: Lineamientos PMO, banco proyectos articulado con PFP, aprobación portafolio. TERMINA: Portafolio aprobado y presupuestado.','% PAC derivado de BEP integrado (≥95%)\n% proyectos con ficha completa (100%)','Jefe Unidad Prospectiva Estratégica','Plan del portafolio de proyectos\nBanco de Proyectos integrado con PFP','Cada proyecto del BEP de GUENAA, GUENE y GUENTIC debe estar inscrito y priorizado para garantizar financiamiento y ejecución.',FALSE,NULL,2),

((SELECT id FROM subprocesos WHERE codigo='SP010101'),'A010101341','Gestionar la Administración de Riesgos Empresariales','INICIA: Identificación de riesgos por proceso. INCLUYE: Mapa de riesgos corporativo, controles y seguimiento trimestral. TERMINA: Informe consolidado de riesgos.','% riesgos corporativos con plan de tratamiento (100%)\nMatriz riesgos actualizada trimestralmente','Jefe Unidad Prospectiva','Mapa de riesgos corporativo\nPlan de tratamiento de riesgos\nInforme trimestral de seguimiento','Vincula riesgos de los 3 negocios: desabastecimiento hídrico (A&A), falla SDL (Energía), ciberseguridad (TIC).',FALSE,NULL,3),

((SELECT id FROM subprocesos WHERE codigo='SP010102'),'A010102009','Planear y Evaluar la Comunicación Empresarial','INICIA: Lineamientos de comunicación interna y externa. INCLUYE: Plan de comunicación, política, metodologías de evaluación. TERMINA: Plan aprobado y acciones implementadas.','% Cumplimiento Plan de Comunicación\nÍndice satisfacción comunicación interna','Jefe Comunicaciones','Plan Estratégico de Comunicación\nPolítica de Comunicación\nIndicadores de impacto','Transversal a los 3 negocios: comunica logros de A&A (calidad del agua), Energía (calidad del servicio) y TIC (nuevos servicios) a usuarios y grupos de interés.',FALSE,NULL,4),

((SELECT id FROM subprocesos WHERE codigo='SP010201'),'A010201014','Planear y Evaluar el Sistema de Gestión de Calidad','INICIA: Requisitos normativos ISO 9001. INCLUYE: Plan anual de calidad, indicadores, programación de auditorías. TERMINA: Plan aprobado por la dirección.','Nivel de madurez SGI (≥3/5)\nPlan de calidad aprobado antes del 31 de enero','Jefe SGI / Calidad','Plan anual de calidad\nObjetivos de calidad por negocio\nProgramación de auditorías','Los objetivos de calidad aplican a procesos de GUENAA (IRCA, continuidad), GUENE (SAIDI/SAIFI) y GUENTIC (disponibilidad servicios).',FALSE,NULL,5),

((SELECT id FROM subprocesos WHERE codigo='SP010201'),'A010201292','Gestionar Auditorías Internas y Externas','INICIA: Programación de auditorías internas y externas. INCLUYE: Preparación, acompañamiento y seguimiento post-auditoría. TERMINA: Hallazgos cerrados y certificaciones renovadas.','% Hallazgos auditados con plan de mejora (100%)\nCertificaciones renovadas en plazo','Jefe SGI / Calidad','Certificados de calidad vigentes\nPlanes de mejora cerrados','Verifica el cumplimiento del SGI en procesos de A&A (calidad agua), Energía (operación SDL) y TIC (disponibilidad servicios).',FALSE,NULL,6),

((SELECT id FROM subprocesos WHERE codigo='SP010202'),'A010202260','Implementar y Aplicar Marcos Normativos y Regulatorios','INICIA: Plan de implementación regulatoria aprobado. INCLUYE: Coordinación con GUENs, actualización de tarifas, adaptación de procesos. TERMINA: Cumplimiento verificado y reportado.','% resoluciones regulatorias implementadas por negocio (100%)\nTarifas actualizadas en plazo','Jefe Regulación Empresarial','Resoluciones regulatorias implementadas\nTarifas actualizadas\nReportes CRA / CREG / CRC','Habilita la defensa tarifaria: A&A (tarifas CRA), Energía (cargos CREG OR/STR), TIC (obligaciones CRC/MinTIC).',FALSE,NULL,7),

((SELECT id FROM subprocesos WHERE codigo='SP010203'),'A010203346','Realizar Inteligencia Competitiva y Vigilancia Tecnológica','INICIA: Definición del radar de vigilancia tecnológica. INCLUYE: Recolección, análisis y comunicación de información estratégica. TERMINA: Informe de inteligencia competitiva publicado.','N° informes de inteligencia competitiva/año (≥4)\nOportunidades identificadas por negocio','Jefe Nuevos Negocios','Informe de inteligencia competitiva\nRadar de tendencias tecnológicas','Identifica oportunidades para A&A (soluciones de agua no reguladas), Energía (microrredes, eficiencia energética) y TIC (servicios cloud, IoT).',FALSE,NULL,8),

((SELECT id FROM subprocesos WHERE codigo='SP010301'),'A010301015','Implementar Programas y Proyectos Ambientales','INICIA: Compromisos del PSMV, PGIRS y permisos de concesión. INCLUYE: Ejecución programas ambientales, gestión de vertimientos, residuos, emisiones. TERMINA: Informes ambientales publicados.','% cumplimiento PSMV\n% compromisos ambientales ejecutados en plazo','Jefe Ambiental','Programas ambientales ejecutados\nInformes de seguimiento ambiental','Sin permisos ambientales vigentes los negocios no pueden operar: concesión agua Río Cauca (A&A), gestión residuos SDL (Energía), residuos electrónicos (TIC).',FALSE,NULL,9)

ON CONFLICT (codigo) DO NOTHING;

-- MP02 – 12 actividades
INSERT INTO actividades (subproceso_id, codigo, descripcion, alcance, indicador, responsable, producto, habilitador_negocio, es_critica, nota_critica, orden) VALUES

((SELECT id FROM subprocesos WHERE codigo='SP020101'),'A020101022','Analizar Comportamiento Integral del Servicio A&A','INICIA: Recopilación de indicadores del período. INCLUYE: Análisis IANC, IRCA, continuidad, recaudo, satisfacción. Benchmarking CRA. TERMINA: Diagnóstico integral y propuestas de mejora.','N° brechas identificadas vs. estándar CRA\nOportunidad del informe de diagnóstico','Jefe Planeación A&A','Diagnóstico integral del servicio A&A\nBenchmarking sectorial\nPropuestas de mejora','El diagnóstico orienta la formulación de proyectos del BEP para mejorar IANC, continuidad e IRCA.',FALSE,NULL,1),

((SELECT id FROM subprocesos WHERE codigo='SP020101'),'A020101025','Formular Plan de Optimización y Expansión Unidades Operacionales','INICIA: Diagnóstico integral del servicio y catastro de redes. INCLUYE: Priorización inversiones, formulación POIR, inscripción en BEP. TERMINA: POIR aprobado e inscrito.','% proyectos POIR inscritos en banco integrado (100%)\n% POIR ejecutado vs. programado (≥85%)','Jefe Planeación A&A','Plan POIR A&A aprobado\nProyectos inscritos en BEP','El POIR es la base del banco de proyectos de A&A: inversiones en redes, PTAP, PTAR y sistemas de captación.',FALSE,NULL,2),

((SELECT id FROM subprocesos WHERE codigo='SP020201'),'A020201027','Captar Agua Cruda','INICIA: Operación de bocatomas y canales de aducción según demanda. INCLUYE: Monitoreo caudales, operación compuertas, registro volúmenes captados. TERMINA: Agua cruda almacenada en tanques de regulación.','Eficiencia captación = Vol. captado/Vol. concesionado (≥95%)\nDisponibilidad sistema captación (≥98%)','Operador de Captación','Agua cruda captada (m³/s)\nConformidad con concesión ambiental','Eslabón 1 cadena de valor A&A: sin captación no hay producción de agua. Habilita directamente la PTAP (eslabón 2).',FALSE,NULL,3),

((SELECT id FROM subprocesos WHERE codigo='SP020201'),'A020201028','Tratar y Controlar Calidad del Agua (PTAP)','INICIA: Recepción de agua cruda en la PTAP. INCLUYE: Coagulación, floculación, sedimentación, filtración, cloración, control de calidad. TERMINA: Agua tratada lista para distribución con IRCA Sin Riesgo.','IRCA mensual (Sin Riesgo <5%)\nm³ tratados/día\nConsumo de reactivos por m³ tratado','Operador PTAP','Agua potable conforme IRCA (m³/día)\nRegistros de laboratorio PTAP','Eslabón 2 cadena de valor A&A: la producción de agua potable habilita la distribución (eslabón 3) y la comercialización (eslabón 4).',FALSE,NULL,4),

((SELECT id FROM subprocesos WHERE codigo='SP020201'),'A020201029','Suministrar Agua Potable a la Red de Distribución','INICIA: Agua potable almacenada en tanques de distribución. INCLUYE: Operación de estaciones de bombeo, control de presiones, monitoreo SCADA. TERMINA: Agua entregada a la red de distribución primaria.','Presión en red de distribución primaria (dentro de norma)\nContinuidad del suministro (%)','Operador Distribución A&A','Agua distribuida a la red primaria (m³/h)\nRegistro de presiones y caudales','Conecta la producción de agua potable (eslabón 2) con la distribución al usuario final (eslabón 3).',FALSE,NULL,5),

((SELECT id FROM subprocesos WHERE codigo='SP020204'),'A020204034','Operar Redes de Acueducto','INICIA: Monitoreo del estado de la red vía SCADA. INCLUYE: Operación válvulas, macromedidores, monitoreo presiones, atención fugas. TERMINA: Red operada y servicio continuo al usuario.','% sectores con servicio continuo (≥20h/día)\nN° fugas reportadas y atendidas en <4h','Operador Redes Acueducto','Red de distribución operada\nRegistros de presión y continuidad','Eslabón 3 cadena de valor A&A: lleva el agua potable al usuario final. Habilita la comercialización (eslabón 4).',FALSE,NULL,6),

((SELECT id FROM subprocesos WHERE codigo='SP020204'),'A020204036','Verificar Condiciones Técnicas del Sistema de Distribución','INICIA: Programación de inspecciones y mediciones en la red. INCLUYE: Medición de presiones, caudales, muestreos de calidad en red, verificación macromedidores. TERMINA: Informe de condiciones técnicas y acciones correctivas.','% puntos de red con presión dentro de norma\n% muestras de calidad conformes IRCA en red','Técnico de Redes A&A','Informe de condiciones técnicas de la red\nRegistros de presión y calidad','Habilita el control de pérdidas (IANC) y la calidad del agua en red (IRCA distribución).',FALSE,NULL,7),

((SELECT id FROM subprocesos WHERE codigo='SP020202'),'A020202063','Procesar Aguas Residuales en PTAR-C','INICIA: Llegada de aguas residuales al punto de entrada de la PTAR-C. INCLUYE: Cribado, desarenado, sedimentación primaria, reactor biológico, sedimentación secundaria. TERMINA: Efluente secundario listo para disposición final.','DBO5 efluente (mg/L) conforme PSMV\nSST efluente (mg/L) conforme norma\nEficiencia remoción DBO5 (≥80%)','Operador PTAR','Agua residual tratada (m³/día)\nConformidad PSMV (DBO5, SST, pH)','Eslabón 6 cadena de valor A&A: cierra el ciclo del agua. Habilita la disposición final conforme al PSMV.',FALSE,NULL,8),

((SELECT id FROM subprocesos WHERE codigo='SP020202'),'A020202065','Realizar Seguimiento y Control del Tratamiento AR','INICIA: Plan de monitoreo operacional y de calidad de la PTAR-C. INCLUYE: Medición de parámetros, análisis de laboratorio, ajuste de procesos. TERMINA: Informe mensual de calidad del efluente.','% parámetros PSMV conformes por muestra\nOportunidad de informes a la CVC','Jefe PTAR-C / Laboratorio','Informes de calidad del efluente\nReportes a CVC/DAACD','Habilita el cumplimiento ambiental de A&A: los datos del efluente son el respaldo técnico ante las autoridades.',FALSE,NULL,9),

((SELECT id FROM subprocesos WHERE codigo='SP020302'),'A020302044','Mantener Medidores de Agua','INICIA: Plan de mantenimiento y renovación del parque de medidores. INCLUYE: Lectura, mantenimiento, calibración y cambio de medidores defectuosos. TERMINA: Parque de medidores activo y calibrado.','% medidores activos vs. conexiones (≥95%)\nError de medición promedio (≤5%)','Técnico Medición A&A','Parque de medidores mantenido\nPlan de renovación ejecutado','Habilita la comercialización A&A y el control del IANC: sin medición precisa no hay facturación correcta ni control de pérdidas comerciales.',FALSE,NULL,10),

((SELECT id FROM subprocesos WHERE codigo='SP020303'),'A020303317','Vender Productos y Servicios A&A','INICIA: Plan de ventas y zonas de expansión. INCLUYE: Prospección de clientes, vinculación, instalación de servicio, gestión de contratos. TERMINA: Usuario vinculado, medidor instalado y primera factura emitida.','N° nuevas conexiones A&A / mes\nIngresos nuevas ventas A&A ($)','Asesor Comercial A&A','Nuevas conexiones instaladas\nContratos de prestación de servicio','Habilita el crecimiento del negocio A&A: la vinculación de nuevos usuarios aumenta los ingresos facturados (eslabón 4).',FALSE,NULL,11),

((SELECT id FROM subprocesos WHERE codigo='SP020303'),'A020303430','Gestionar Aseguramiento de Ingresos A&A','INICIA: Análisis de la cartera y balance de ingresos facturados vs. recaudados. INCLUYE: Gestión de cartera morosa, control de tarifas, recuperación de ingresos, reportes SUI. TERMINA: Informe de aseguramiento de ingresos.','Eficiencia recaudo A&A (≥92%)\nCartera vencida >90 días (≤8% cartera total)','Jefe Aseguramiento Ingresos A&A','Informe de aseguramiento de ingresos\nTarifas actualizadas en SUI','Asegura que los ingresos generados por la prestación del servicio se traduzcan efectivamente en recaudo.',FALSE,NULL,12)

ON CONFLICT (codigo) DO NOTHING;

-- MP03 – 9 actividades
INSERT INTO actividades (subproceso_id, codigo, descripcion, alcance, indicador, responsable, producto, habilitador_negocio, es_critica, nota_critica, orden) VALUES

((SELECT id FROM subprocesos WHERE codigo='SP030101'),'A030101089','Definir, Formular y Evaluar la Planeación Técnica del SDL','INICIA: Análisis de la demanda proyectada y estado de la infraestructura. INCLUYE: Plan de expansión y reposición, estudios de confiabilidad, EBIE, fichas proyectos CREG. TERMINA: Plan de Inversión SDL aprobado.','% cumplimiento Plan Inversión SDL (≥90%)\nEstudios de confiabilidad actualizados','Jefe Planeación GUENE','Plan de Inversión SDL aprobado\nEBIE actualizado\nFichas de proyectos registradas en UPME','Sin plan de inversiones del SDL no hay expansión ni reposición de la infraestructura de distribución.',FALSE,NULL,1),

((SELECT id FROM subprocesos WHERE codigo='SP030201'),'A030201093','Distribuir Energía Eléctrica','INICIA: Recibo de energía en barras de subestaciones del SDL. INCLUYE: Operación subestaciones, transformadores, redes MT y BT, monitoreo SCADA, despacho. TERMINA: Energía entregada al usuario final con SAIDI/SAIFI conformes.','SAIDI y SAIFI dentro de OM CREG\nFactor de utilización transformadores (≤80%)','Operador Centro de Control','Energía distribuida (kWh)\nSistema monitoreado y operado','Eslabón 4 cadena de valor energía (Distribución SDL): proceso central del negocio regulado. Habilita la comercialización y el alumbrado público.',FALSE,NULL,2),

((SELECT id FROM subprocesos WHERE codigo='SP030202'),'A030202102','Ejecutar el Mantenimiento del SDL','INICIA: Programación de mantenimientos preventivos y recepción de órdenes correctivas. INCLUYE: Mantenimiento redes MT/BT, subestaciones, reconectadores, transformadores. TERMINA: SDL mantenido, disponible y con certificaciones vigentes.','% mantenimientos preventivos ejecutados (≥90%)\nN° fallas post-mantenimiento (meta: 0)','Técnico de Mantenimiento SDL','SDL mantenido y disponible\nCertificaciones RETIE vigentes','El mantenimiento asegura la disponibilidad y confiabilidad del sistema, reduciendo el SAIDI y el SAIFI.',FALSE,NULL,3),

((SELECT id FROM subprocesos WHERE codigo='SP030206'),'A030206112','Desarrollar Planes de Disminución de Pérdidas','INICIA: Identificación de zonas críticas de pérdidas en el SDL. INCLUYE: Inspecciones, detección conexiones ilegales, revisión medidores, normalizaciones. TERMINA: kWh recuperados registrados y facturados.','kWh recuperados/mes vs. meta\n% reducción índice de pérdidas','Técnico Control Pérdidas Energía','kWh recuperados y facturados\nInforme de intervenciones','Cada punto de reducción en el índice de pérdidas genera ingresos adicionales para GUENE.',FALSE,NULL,4),

((SELECT id FROM subprocesos WHERE codigo='SP030204'),'A030204415','Gestionar Operación Administrativa, Financiera y Técnica AP','INICIA: Plan operativo del SALP y obligaciones del contrato con la Alcaldía. INCLUYE: Gestión técnica, administrativa, supervisión contratistas, facturación municipio, PQR. TERMINA: SALP disponible y factura mensual emitida.','Disponibilidad SALP (≥95%)\nFacturación AP oportuna','Jefe SALP','SALP operativo\nFacturación mensual al municipio','Negocio no regulado de Energía: el SALP genera ingresos complementarios para GUENE a través del contrato con la Alcaldía de Cali.',FALSE,NULL,5),

((SELECT id FROM subprocesos WHERE codigo='SP030302'),'A030302080','Realizar la Compra de Energía en el MEM','INICIA: Análisis de la demanda proyectada y precio de mercado. INCLUYE: Suscripción de contratos, operaciones en bolsa, registro ASIC/XM, gestión de coberturas. TERMINA: Contratos registrados y energía comprada dentro del presupuesto.','Costo unitario compra energía ($/kWh)\n% cumplimiento presupuesto de compra','Trader / Analista Mercado Energético','Contratos de suministro de energía\nRegistros ASIC','Eslabón 2 cadena de valor energía: la compra eficiente es la base del costo del servicio para los usuarios del mercado regulado (MR).',FALSE,NULL,6),

((SELECT id FROM subprocesos WHERE codigo='SP030303'),'A030303360','Ejecutar la Comercialización y Venta de Energía','INICIA: Plan de comercialización y base de clientes activos. INCLUYE: Facturación MR, gestión contratos MNR, prospección grandes clientes, retención. TERMINA: Contratos MNR vigentes y facturas MR emitidas.','N° clientes MNR activos vs. meta\nIngresos MNR / Total ingresos energía (%)','Asesor Comercial Energía','Contratos MNR vigentes\nFacturas MR emitidas','Eslabón 8 cadena de valor energía: genera los ingresos del negocio a partir de la distribución del SDL y la compra en el MEM.',FALSE,NULL,7),

((SELECT id FROM subprocesos WHERE codigo='SP030303'),'A030303361','Gestionar Recaudo y Aseguramiento de Ingresos Energía','INICIA: Análisis de cartera energía y balance de ingresos. INCLUYE: Gestión cartera morosa, recuperación ingresos, control tarifario, reportes XM. TERMINA: Informe de aseguramiento de ingresos energía.','Eficiencia recaudo energía (≥95%)\nCartera vencida >60 días (≤5% cartera total)','Jefe Aseguramiento Ingresos Energía','Informe aseguramiento ingresos energía\nReportes XM y SSPD actualizados','Garantiza que la energía distribuida y comercializada se traduzca efectivamente en recaudo para GUENE.',FALSE,NULL,8),

((SELECT id FROM subprocesos WHERE codigo='SP030302'),'A030302081','Gestionar Contratos de Interconexión y Uso de Infraestructura (UDI)','INICIA: Solicitud de uso de infraestructura eléctrica por terceros (operadores cable/telecom). INCLUYE: Aforos, contratos UDI, facturación, revisión proyectos de terceros. TERMINA: Contratos vigentes y facturación UDI ejecutada.','Ingresos no operacionales UDI vs. año anterior (≥+5%)\nAforos actualizados (%)','Jefe UDI GUENE','Contratos UDI vigentes\nFacturación UDI mensual','Negocio no regulado de Energía: el UDI genera ingresos complementarios aprovechando la infraestructura eléctrica existente del SDL.',FALSE,NULL,9)

ON CONFLICT (codigo) DO NOTHING;

-- MP04 – 5 actividades
INSERT INTO actividades (subproceso_id, codigo, descripcion, alcance, indicador, responsable, producto, habilitador_negocio, es_critica, nota_critica, orden) VALUES

((SELECT id FROM subprocesos WHERE codigo='SP040101'),'A040101114','Realizar Planeación Estratégica Prestación Servicios TIC','INICIA: Análisis del mercado TIC y regulación MinTIC/CRC. INCLUYE: Cuadro de mando, plan de acción, BEP TIC, proyecciones financieras, regulación. TERMINA: Plan estratégico UENTIC aprobado y comunicado.','Cumplimiento plan estratégico UENTIC (%)\n% obligaciones MinTIC cumplidas (100%)','Jefe Planeación GUENTIC','Plan estratégico UENTIC\nCuadro de mando TIC\nBEP TIC con proyecciones','El plan estratégico orienta las inversiones en red, el desarrollo de nuevos productos y la estrategia comercial por segmento.',FALSE,NULL,1),

((SELECT id FROM subprocesos WHERE codigo='SP040202'),'A040202144','Gestionar la Ejecución de Proyectos TIC','INICIA: Contrato de suministro o construcción de red TIC aprobado. INCLUYE: Supervisión de obra, control avance físico/financiero, interventoría, entrega operacional. TERMINA: Activos de red transferidos a operación.','% avance físico-financiero vs. cronograma\n% proyectos completados en plazo (≥85%)','Supervisor Proyectos TIC','Actas de seguimiento de obra\nActivos activados en SAP AM','Eslabón 3 cadena de valor TIC: la implementación de proyectos es la base del crecimiento de la infraestructura TIC para B2C, B2B y B2G.',FALSE,NULL,2),

((SELECT id FROM subprocesos WHERE codigo='SP040301'),'A040301131','Soportar y Operar los Servicios de Conectividad e Internet','INICIA: Monitoreo de la red de acceso y plataformas de internet. INCLUYE: Operación plataforma BNG/BRAS, gestión ancho de banda, resolución de incidencias. TERMINA: Servicios de internet disponibles dentro del ANS.','Disponibilidad servicio internet (≥99.5%)\nTiempo promedio resolución de incidencias (h)','Operador NOC TIC','Servicios internet disponibles (% uptime)\nTickets de incidencia resueltos','Eslabón 4 cadena de valor TIC: la operación de servicios habilita la comercialización B2C, B2B y B2G de GUENTIC.',FALSE,NULL,3),

((SELECT id FROM subprocesos WHERE codigo='SP040404'),'A040404272_B2C','Ejecutar Ventas de Servicios TIC – Segmento B2C (Hogares)','INICIA: Plan de ventas B2C y base de prospectos residenciales. INCLUYE: Prospección, visitas, propuestas, instalación y activación. TERMINA: Contrato firmado y cliente en base activa.','N° nuevos contratos B2C / mes\nChurn B2C (≤2%)','Asesor Comercial TIC B2C','Nuevos contratos B2C\nIngresos por nuevas ventas residenciales','Eslabón 6 cadena de valor TIC (segmento residencial): genera los ingresos masivos del negocio TIC aprovechando la red de fibra óptica.',FALSE,NULL,4),

((SELECT id FROM subprocesos WHERE codigo='SP040404'),'A040404272_B2B','Ejecutar Ventas de Servicios TIC – Segmento B2B/B2G (Empresas y Gobierno)','INICIA: Plan de ventas B2B/B2G y base de prospectos corporativos. INCLUYE: Prospección, propuestas técnico-comerciales, suscripción contratos, activación. TERMINA: Contratos B2B/B2G firmados y servicios activos.','N° contratos B2B/B2G activos vs. meta\nIngresos B2B/B2G / Total ingresos TIC (%)','Asesor Comercial TIC B2B/B2G','Contratos B2B/B2G vigentes\nIngresos por segmentos corporativos','Eslabón 6 cadena de valor TIC (corporativo y gobierno): los contratos B2B/B2G son los de mayor valor unitario y menor churn del negocio TIC.',FALSE,NULL,5)

ON CONFLICT (codigo) DO NOTHING;

-- MP05 – 4 actividades (+ 2 críticas)
INSERT INTO actividades (subproceso_id, codigo, descripcion, alcance, indicador, responsable, producto, habilitador_negocio, es_critica, nota_critica, orden) VALUES

((SELECT id FROM subprocesos WHERE codigo='SP050101'),'A050101001','Gestionar la Nómina y Prestaciones Sociales','INICIA: Recopilación de novedades de nómina del período. INCLUYE: Liquidación nómina, prestaciones sociales, parafiscales, descuentos por convenio. TERMINA: Nómina pagada e informes de costo laboral por negocio.','% nómina liquidada sin error (100%)\nCosto nómina por negocio correctamente imputado','Analista de Nómina','Nómina liquidada y pagada\nCosto laboral por negocio\nInformes de parafiscales','El pago oportuno asegura la disponibilidad del personal para operar GUENAA (operadores PTAP/PTAR), GUENE (técnicos SDL) y GUENTIC (NOC).',FALSE,NULL,1),

((SELECT id FROM subprocesos WHERE codigo='SP050102'),'A050102001','Documentar Conocimiento Tácito de Operadores Senior','INICIA: Identificación de los 50 cargos críticos con riesgo de jubilación en 1-3 años. INCLUYE: Entrevistas técnicas, shadowing, elaboración de manuales operativos, banco de conocimiento. TERMINA: Banco de conocimiento técnico disponible y programa de mentoring activo.','% procesos críticos documentados (≥80%)\nN° manuales operativos publicados','Jefe TH','Manuales operativos por proceso crítico\nBanco de conocimiento técnico\nPrograma de mentoring activo','⚡ URGENTE: Sin esta acción, EMCALI perderá en 5-8 años el 65% de su planta (≈1.600 funcionarios) con conocimiento tácito crítico de PTAP, PTAR, SDL y plataformas TIC.',TRUE,'ACCIÓN URGENTE: 65% de la planta supera los 50 años. Riesgo de pérdida masiva de conocimiento operativo crítico en los 3 negocios. Implementar en los primeros 6 meses.',2),

((SELECT id FROM subprocesos WHERE codigo='SP050201'),'A050201001','Gestionar Contabilidad Regulatoria por Negocio','INICIA: Creación de los centros de costo regulatorios en SAP (Mes 2-3). INCLUYE: Asignación de costos por eslabón (CC-AA-CAP, CC-AA-TRT, CC-AA-DST, CC-EN-SDL, CC-TIC-CAP, etc.), metodología ABC. TERMINA: EEFF regulatorios por negocio presentados a CRA/CREG/CRC.','% costos directos asignados a eslabón (≥95%)\nN° incumplimientos reportes regulatorios (meta: 0)','Contador Regulatorio','EEFF por negocio (CRA/CREG/CRC)\nContabilidad regulatoria activa en SAP\nCostos ABC por actividad MOP','⚡ URGENTE: Sin contabilidad regulatoria separada, EMCALI no puede defender sus tarifas ante CRA (A&A), CREG (Energía) ni CRC (TIC).',TRUE,'ACCIÓN URGENTE MES 2-3: Crear 15 centros de costo regulatorios en SAP. Implementar metodología ABC para asignación de costos compartidos. Base para defensa tarifaria ante reguladores.',3),

((SELECT id FROM subprocesos WHERE codigo='SP050301'),'A050301001','Consolidar y Ejecutar el Plan Anual de Contratación (PACC)','INICIA: Recopilación de necesidades de contratación de los 3 negocios y áreas. INCLUYE: Consolidación del PACC, priorización, cronograma de procesos, aprobación. TERMINA: PACC aprobado por la Gerencia y publicado en el SECOP.','% PACC ejecutado en fecha programada (≥85%)\nN° contratos no planificados (meta: reducción anual)','Jefe Abastecimiento','PACC consolidado y aprobado\nCronograma de procesos\nInformes de ejecución PACC','Habilita los 3 negocios: el PACC oportuno asegura reactivos para PTAP (A&A), materiales para mantenimiento SDL (Energía) y equipos para expansión de red TIC.',FALSE,NULL,4)

ON CONFLICT (codigo) DO NOTHING;

