((SELECT id FROM actividades WHERE codigo='A020201028'),'Área Técnica PTAP','Operar las plantas de potabilización. Garantizar el IRCA Sin Riesgo. Optimizar el uso de reactivos. Gestionar los procesos de tratamiento.','IRCA mensual promedio (%)\n% eficiencia de tratamiento (m³ tratados/m³ ingresados)','m³ de agua potable producidos / turno'),
((SELECT id FROM actividades WHERE codigo='A030201093'),'Centro de Control de Energía','Operar el SDL desde el Centro de Control. Gestionar contingencias. Monitorear SAIDI y SAIFI en tiempo real. Coordinar maniobras de campo.','SAIDI y SAIFI (conforme OM CREG)\nDisponibilidad del Centro de Control (%)','kWh distribuidos por turno / N° operadores'),
((SELECT id FROM actividades WHERE codigo='A040301131'),'NOC – Centro de Operaciones de Red TIC','Monitorear y operar las plataformas TIC 24/7. Gestionar incidencias. Garantizar los ANS. Coordinar la resolución de problemas.','Disponibilidad plataformas TIC (%)\n% tickets resueltos dentro del SLA','N° incidencias resueltas / operador / turno'),
((SELECT id FROM actividades WHERE codigo='A050102001'),'Área de Gestión del Conocimiento','Gestionar el programa de gestión del conocimiento. Supervisar la documentación de procesos críticos. Administrar el banco de conocimiento técnico.','% procesos críticos documentados vs. identificados\nN° manuales operativos publicados en el año','N° procesos críticos documentados / analista / año'),
((SELECT id FROM actividades WHERE codigo='A050201001'),'Área de Contabilidad Regulatoria','Gestionar la contabilidad regulatoria de los 3 negocios. Mantener los centros de costo en SAP. Preparar los EEFF regulatorios. Aplicar la metodología ABC.','% costos críticos con trazabilidad regulatoria\nOportunidad de presentación EEFF a reguladores','N° centros de costo regulatorios activos / total requeridos');

